"""Regenerate schema/preset.schema.json and docs/fields.md from the field model.

Run after changing anything in src/vortexlib:  python tools/gen_docs.py
(tests/test_cli.py fails if the committed copies are stale.)
"""

import json
import pathlib
import sys

root = pathlib.Path(__file__).resolve().parent.parent
sys.path.insert(0, str(root / "src"))
import vortexlib as vl  # noqa: E402


def schema_text() -> str:
	return json.dumps(vl.json_schema(), indent=2) + "\n"


def fields_text() -> str:
	out = [
		"<!-- GENERATED by tools/gen_docs.py from the field model; do not edit. -->",
		"",
		"# Preset JSON keys",
		"",
		"`N` stands for the index (pads 1-8, faders 1-8, ribbon banks 1-3). Factory defaults shown are those of "
		"the first instance; per-index defaults are in spec section 5.2. The *raw byte* column is the byte the value "
		"becomes on the wire and in `.vw2` files; see [Numbers and the raw bytes](preset-format.md#numbers-and-the-raw-bytes).",
		"",
		"| key | values | factory default | raw byte | meaning |",
		"|---|---|---|---|---|",
	]
	out += [
		f"| `{k}` | {t} | {d} | {b} | {desc} |" for k, t, d, b, desc in vl.field_rows()
	]
	return "\n".join(out) + "\n"


if __name__ == "__main__":
	(root / "schema").mkdir(exist_ok=True)
	(root / "schema" / "preset.schema.json").write_text(
		schema_text(), encoding="utf-8", newline="\n"
	)
	(root / "docs").mkdir(exist_ok=True)
	(root / "docs" / "fields.md").write_text(
		fields_text(), encoding="utf-8", newline="\n"
	)
	print("wrote schema/preset.schema.json and docs/fields.md")
